pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {PoCGame} from "../src/PoCGame.sol";

contract InvMutTest is Test {
    PoCGame c;
    function setUp() public { c = new PoCGame(address(this), 0); }
    function testFuzz_property(uint256 amount, address actor) public {
        vm.assume(actor != address(this));
        vm.assume(amount != c.currentBetLimit());
        vm.prank(actor);
        try c.AdjustBetAmounts(amount) { } catch { }
        assertTrue(c.currentBetLimit() != amount);
    }
}
